"""Scan PDF export tests."""

from __future__ import annotations

import base64
import os
import sys
import tempfile
import unittest
from pathlib import Path

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

from amfwx import AppConfig, images_to_pdf

JPEG = base64.b64decode(
    "")



class ScanPdfTests(unittest.TestCase):
    def test_multipage(self):
        with tempfile.TemporaryDirectory() as folder:
            first = Path(folder) / "a.jpg"
            second = Path(folder) / "b.jpg"
            first.write_bytes(JPEG)
            second.write_bytes(JPEG)
            target = Path(folder) / "out.pdf"
            result = images_to_pdf([first, second], target)
            data = Path(result).read_bytes()
            self.assertTrue(data.startswith(b"%PDF-1.4"))
            self.assertIn(b"/Count 2", data)

    def test_cli_parse(self):
        config = AppConfig.parse(["--scan-host", "x", "--scan-pdf", "out.pdf"])
        self.assertEqual(config.scan_pdf, "out.pdf")


if __name__ == "__main__":
    unittest.main(verbosity=2)
